const input = $input.first().json;
const { whatsapp, tags } = input;

if (!whatsapp) {
  throw new Error('whatsapp es requerido');
}

if (!tags || tags.length === 0) {
  throw new Error('tags es requerido y debe ser un array');
}

const tagsStr = Array.isArray(tags) ? tags.join(',') : tags;
const validTags = ['KIDS', 'KIDS-ADOLESCENTES', 'ADULTOS-REGULAR GRUPAL', 'PERSONALIZADO', 'AU_PAIR'];
const tagsArray = tagsStr.split(',').map(t => t.trim());

const invalidTags = tagsArray.filter(tag => !validTags.includes(tag));
if (invalidTags.length > 0) {
  throw new Error(`Tags inválidos: ${invalidTags.join(', ')}. Tags válidos: ${validTags.join(', ')}`);
}

const query = `UPDATE alumnos SET tags = '${tagsStr}', updated_at = NOW() WHERE whatsapp = '${whatsapp}' RETURNING id, whatsapp, nombre, tags`;

return [{ json: { query, whatsapp, tags: tagsStr } }];

const result = $('Actualizar tags').first()?.json;

let response = {
  success: false,
  alumno: null
};

if (result) {
  response.success = true;
  response.alumno = {
    whatsapp: result.whatsapp,
    nombre: result.nombre,
    tags: result.tags
  };
} else {
  response.error = 'Alumno no encontrado';
}

return [{ json: response }];
